import { jev } from "../../core/client.ts";
import type { Question } from "../../core/types.ts";

export type SchemaOption = {
  key: string; id: string; name: string; blurb: string; spec: string; version: string;
  questions: Record<string, Question>; review_floor: number; input_schema: Record<string, unknown>;
  inputs: Record<string, unknown>[];
};

export type PolicyResult = { status: string; outcome: string | null; rule: string } | null;

export type Built = {
  errors: { field: string; message: string }[];
  state: Record<string, unknown> | null; questions: Record<string, Question> | null;
  precheck: { proceed: boolean; status: string | null; outcome: string | null; rule: string | null } | null;
};

export type Hooks = {
  build: () => Promise<Built>;
  policy?: (answers: Record<string, any>, state?: Record<string, unknown>) => Promise<PolicyResult>;
};

export type SchemaDecision = {
  pick: string;
  confidence: number | null;
  outcome?: string | null;
  status?: string;
  rule?: string;
  gate?: "proceed" | "human review";
  policy?: "policy engine offline";
};

export async function schemaDecision(option: SchemaOption, hooks: Hooks): Promise<SchemaDecision> {
  const built = await hooks.build();
  if (built.errors.length || !built.state || !built.questions || !built.precheck?.proceed) {
    const p = hooks.policy ? await hooks.policy({}) : null;
    const pick = built.errors.length ? "invalid input" : `precheck ${built.precheck?.rule}`;
    return { pick, confidence: null, outcome: p?.outcome ?? built.precheck?.outcome ?? "none",
             status: p?.status ?? (built.errors.length ? "failed" : built.precheck?.status ?? "failed"),
             rule: p?.rule ?? (built.errors.length ? "input_schema" : built.precheck?.rule ?? "precheck") };
  }
  const { answers } = await jev.systemOne(built.state, built.questions);
  const [id, a] = Object.entries(answers)[0] as [string, any];
  const pick = a.type === "noul" ? `${id} ${a.noul >= 0.5 ? "yes" : "no"}` : a.type === "choice" ? a.choice : `${id} ${a.score.toFixed(2)}`;
  const confidence = a.type === "noul" ? Math.max(a.noul, 1 - a.noul) : a.confidence;
  const p = hooks.policy ? await hooks.policy(answers, built.state) : null;
  if (p) return { pick, confidence, outcome: p.outcome ?? "none", status: p.status, rule: p.rule };
  return { pick, confidence, gate: confidence >= option.review_floor ? "proceed" : "human review", policy: "policy engine offline" };
}

