import { jev } from "../../core/client.ts";
import { choice, noul } from "../../core/helpers.ts";
import type { ChoiceAnswer, NoulAnswer } from "../../core/types.ts";
import { CONFIDENCE } from "./confidence.ts";

export type CommandSafety = {
  classification: "read_only" | "reversible" | "irreversible";
  run: boolean;
  requiresHuman: boolean;
  confidence: number;
};

export async function gateShellCommand(command: string, cwd: string): Promise<CommandSafety> {
  const { answers } = await jev.systemOne({ command, cwd }, {
    risk: choice("Classify the effect of running `command` in `cwd`.", {
      read_only: "Only reads files, state, or output; changes nothing",
      reversible: "Writes, moves, or creates, but is undoable with git or a backup",
      irreversible: "Deletes, force-pushes, rewrites history, deploys, or touches outside the repo",
    }),
    touches_outside_repo: noul("Does `command` modify anything outside `cwd`?"),
    destructive_intent: noul("Does `command` delete files, drop data, or force-push?"),
  });
  return decideCommandSafety(
    answers.risk as ChoiceAnswer,
    answers.touches_outside_repo as NoulAnswer,
    answers.destructive_intent as NoulAnswer
  );
}

export function decideCommandSafety(
  risk: ChoiceAnswer,
  touchesOutside: NoulAnswer,
  destructive: NoulAnswer
): CommandSafety {
  const classification = risk.choice as CommandSafety["classification"];
  const requiresHuman =
    risk.confidence < CONFIDENCE.REVIEW_FLOOR ||
    (classification !== "read_only" && risk.confidence < CONFIDENCE.DESTRUCTIVE_BAR) ||
    destructive.noul > 0.6 ||
    touchesOutside.noul > 0.6;
  return {
    classification,
    run: classification === "read_only" && risk.confidence >= CONFIDENCE.REVIEW_FLOOR,
    requiresHuman,
    confidence: risk.confidence,
  };
}

import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import type { ChoiceAnswer } from "../../core/types.ts";
import { CONFIDENCE } from "./confidence.ts";

export type AccountAction =
  | { kind: "auto"; action: string }
  | { kind: "confirm"; action: string }
  | { kind: "human"; reason: string };

export async function routeAccountAction(userMessage: string): Promise<AccountAction> {
  const { answers } = await jev.systemOne({ message: userMessage }, {
    action: choice("What is the user trying to do in `message`?", {
      check_balance: "View the account balance",
      approve_transfer: "Approve the pending withdrawal",
      support: "Get help with a problem",
    }),
  });
  return decideAccountAction(answers.action as ChoiceAnswer);
}

export function decideAccountAction(a: ChoiceAnswer): AccountAction {
  if (a.confidence < CONFIDENCE.REVIEW_FLOOR) {
    return { kind: "human", reason: `low confidence (${a.confidence.toFixed(2)})` };
  }
  if (a.choice === "approve_transfer") {
    if (a.confidence > CONFIDENCE.DESTRUCTIVE_BAR) return { kind: "auto", action: "approve_transfer" };
    return { kind: "confirm", action: "approve_transfer" };
  }
  return { kind: "auto", action: a.choice };
}

import { jev } from "../../core/client.ts";
import { choice, score } from "../../core/helpers.ts";
import type { ChoiceAnswer, ScoreAnswer } from "../../core/types.ts";
import { CONFIDENCE } from "./confidence.ts";

export type CitationVerdict = {
  supported: boolean;
  flagForReview: boolean;
  confidence: number;
};

export async function checkCitation(claim: string, quote: string, sourceContext: string): Promise<CitationVerdict> {
  const { answers } = await jev.systemOne({ claim, quote, source_context: sourceContext }, {
    supports: choice("Does `source_context` around `quote` support `claim`?", {
      supports: "The context clearly states or implies the claim",
      contradicts: "The context states the opposite of the claim",
      unrelated: "The context does not address the claim either way",
    }),
    quote_accuracy: score("How faithful is `quote` to the wording in `source_context`?", [
      "Paraphrased or altered in a way that changes meaning",
      "Loose but preserves meaning",
      "Verbatim or trivially elided",
    ]),
  });
  return decideCitation(answers.supports as ChoiceAnswer, answers.quote_accuracy as ScoreAnswer);
}

export function decideCitation(supports: ChoiceAnswer, quoteAccuracy: ScoreAnswer): CitationVerdict {
  const supported = supports.choice === "supports" && supports.confidence >= 0.6 && quoteAccuracy.score >= 1;
  return {
    supported,
    flagForReview: supports.confidence < CONFIDENCE.REVIEW_FLOOR || quoteAccuracy.confidence < 0.5,
    confidence: Math.min(supports.confidence, quoteAccuracy.confidence),
  };
}
